-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

CREATE OR REPLACE FUNCTION public.unbury_cards(cards jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  action uuid := gen_random_uuid();
  card jsonb;
  n integer := 0;
begin
  if not public.is_allowed_user() then
    raise exception 'not_allowed' using errcode = '42501';
  end if;
  perform public.lock_user_study();
  for card in select * from jsonb_array_elements(cards) loop
    if public.browse_change_card(action, 'unbury', card, now(), '{"buried_until": null}'::jsonb) then
      n := n + 1;
    end if;
  end loop;
  return n;
end;
$function$;

grant execute on function public.unbury_cards(cards jsonb) to authenticated;
grant execute on function public.unbury_cards(cards jsonb) to service_role;
